const detail = $json || {};

const decodeBase64Url = (value) => {
  if (!value) return '';
  try {
    const normalized = String(value).replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized + '='.repeat((4 - (normalized.length % 4)) % 4);
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return '';
  }
};

const stripHtml = (value) => String(value || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim();

const collectParts = (node, bucket = []) => {
  if (!node || typeof node !== 'object') return bucket;
  bucket.push(node);
  if (Array.isArray(node.parts)) {
    for (const part of node.parts) {
      collectParts(part, bucket);
    }
  }
  return bucket;
};

const extractBody = (payload) => {
  const nodes = collectParts(payload, []);
  const plainPart = nodes.find((part) => part?.mimeType === 'text/plain' && part?.body?.data);
  if (plainPart?.body?.data) {
    return decodeBase64Url(plainPart.body.data).replace(/\s+/g, ' ').trim();
  }
  const htmlPart = nodes.find((part) => part?.mimeType === 'text/html' && part?.body?.data);
  if (htmlPart?.body?.data) {
    return stripHtml(decodeBase64Url(htmlPart.body.data));
  }
  const fallbackPart = nodes.find((part) => part?.body?.data);
  if (fallbackPart?.body?.data) {
    return stripHtml(decodeBase64Url(fallbackPart.body.data));
  }
  return '';
};

if (!detail.payload) {
  return [{
    json: {
      id: detail.id || detail.messageId || 'unknown',
      error: detail.message || detail.error || 'Failed to fetch email detail',
      failed: true,
    }
  }];
}

const headers = Array.isArray(detail.payload.headers) ? detail.payload.headers : [];
const getHeader = (name) => headers.find((header) => String(header.name || '').toLowerCase() === name.toLowerCase())?.value || '';
const bodyText = extractBody(detail.payload);
const normalizedBody = (bodyText || detail.snippet || '').slice(0, 1200);

return [{
  json: {
    id: detail.id || '',
    threadId: detail.threadId || '',
    from: getHeader('From'),
    subject: getHeader('Subject'),
    date: getHeader('Date'),
    snippet: detail.snippet || '',
    body: normalizedBody,
    labelIds: Array.isArray(detail.labelIds) ? detail.labelIds : [],
    failed: false,
  }
}];

const body = $json.body || {};
const googleAccessToken = body.google_access_token || body.google_token?.access_token || '';
const userId = String(body.user_id || body.userId || '').trim();

if (!googleAccessToken) {
  throw new Error('google_access_token is required for email summary');
}

return [{
  json: {
    user_id: userId,
    requested_at: body.timestamp || new Date().toISOString(),
    google_access_token: googleAccessToken,
    gmail_query: String(body.gmail_query || 'is:unread newer_than:7d').trim(),
    gmail_max_results: Number(body.gmail_max_results || 5),
  }
}];

const inputItems = $input.all();
const detailedEmails = [];
const fetchErrors = [];

for (const item of inputItems) {
  const detail = item.json || {};

  if (detail.failed) {
    fetchErrors.push({
      id: detail.id || 'unknown',
      error: detail.error || 'Failed to fetch email detail',
    });
    continue;
  }

  detailedEmails.push({
    id: detail.id || '',
    threadId: detail.threadId || '',
    from: detail.from || '',
    subject: detail.subject || '',
    date: detail.date || '',
    snippet: detail.snippet || '',
    body: detail.body || '',
    labelIds: Array.isArray(detail.labelIds) ? detail.labelIds : [],
  });
}

return [{
  json: {
    emails: detailedEmails,
    source_metrics: {
      total_unread: detailedEmails.length + fetchErrors.length,
      fetched_email_count: detailedEmails.length,
      fetched_message_ids: detailedEmails.map((e) => e.id),
      failed_message_ids: fetchErrors.map((item) => item.id),
    },
    fetch_error: fetchErrors.length ? `Gagal mengambil detail ${fetchErrors.length} email unread` : null,
    fetch_error_details: fetchErrors.slice(0, 5),
  }
}];

const listPayload = $json || {};
const messages = Array.isArray(listPayload.messages) ? listPayload.messages : [];

return [{
  json: {
    emails: [],
    source_metrics: {
      total_unread: listPayload.resultSizeEstimate || 0,
      fetched_email_count: 0,
      fetched_message_ids: messages.map((message) => message.id),
      failed_message_ids: [],
    },
    fetch_error: null,
    fetch_error_details: [],
  }
}];

const raw = String($json.output || $json.text || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch {
    parsed = {};
  }
}

return [{
  json: {
    success: true,
    user_id: parsed.user_id || '',
    generated_at: new Date().toISOString(),
    summary: {
      domain: 'email',
      status: parsed.status || 'partial',
      priority: parsed.priority || 'medium',
      headline: parsed.headline || 'Ringkasan email belum tersedia',
      summary_points: Array.isArray(parsed.summary_points) ? parsed.summary_points.slice(0, 4) : [],
      recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations.slice(0, 3) : [],
      source_metrics: parsed.source_metrics || {},
    }
  }
}];

return [{
  json: {
    success: true,
    user_id: $json.user_id || '',
    generated_at: $json.generated_at || new Date().toISOString(),
    summary: $json.summary || null,
  }
}];

const body = $json.body ?? {};
const documentId = body.document_id || body.selected_document_id || null;
const userId = body.user_id || null;
const question = String(body.message || '').trim();

if (!question) {
  throw new Error('message is required for document chat');
}

if (!documentId) {
  throw new Error('document_id is required for document chat');
}

if (!userId) {
  throw new Error('user_id is required for document chat');
}

return [{
  json: {
    ...$json,
    body: {
      ...body,
      message: question,
      question,
      document_id: documentId,
      user_id: userId,
      document_name: body.document_name || 'Dokumen terpilih',
    },
  },
}];

const source = $json || {};
const rawEvents = Array.isArray(source.items)
  ? source.items
  : Array.isArray(source.events)
    ? source.events
    : source.summary || source.start || source.end
      ? [source]
      : [];
const events = rawEvents.slice(0, 5);
const now = new Date();

const getStartValue = (event) => event?.start?.dateTime || event?.start?.date || null;
const getEndValue = (event) => event?.end?.dateTime || event?.end?.date || null;
const formatters = {
  dateTime: new Intl.DateTimeFormat('id-ID', {
    timeZone: 'Asia/Jakarta',
    weekday: 'short',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }),
  dateOnly: new Intl.DateTimeFormat('id-ID', {
    timeZone: 'Asia/Jakarta',
    weekday: 'short',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }),
};

const formatEventLabel = (value, isAllDay = false) => {
  if (!value) return '-';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return isAllDay ? formatters.dateOnly.format(parsed) : formatters.dateTime.format(parsed);
};

const normalizedEvents = events.map((event) => {
  const startValue = getStartValue(event);
  const endValue = getEndValue(event);
  const isAllDay = Boolean(event?.start?.date && !event?.start?.dateTime);
  const start = startValue ? new Date(startValue) : null;
  const end = endValue ? new Date(endValue) : null;
  const attendeeEmails = Array.isArray(event.attendees)
    ? event.attendees.map((attendee) => attendee?.email).filter(Boolean)
    : [];

  let status = 'unknown';
  if (start && end && !Number.isNaN(start.getTime()) && !Number.isNaN(end.getTime())) {
    if (now >= start && now <= end) status = 'ongoing';
    else if (now < start) status = 'upcoming';
    else status = 'past';
  }

  return {
    id: event.id || null,
    summary: event.summary || '(Tanpa judul)',
    description: event.description || '',
    location: event.location || '',
    hangoutLink: event.hangoutLink || '',
    is_all_day: isAllDay,
    start_iso: startValue,
    end_iso: endValue,
    start_label: formatEventLabel(startValue, isAllDay),
    end_label: formatEventLabel(endValue, isAllDay),
    attendee_count: attendeeEmails.length,
    attendees: attendeeEmails,
    status,
    htmlLink: event.htmlLink || '',
  };
});

const todayKey = formatters.dateOnly.format(now);
const todayEvents = normalizedEvents.filter((event) => {
  if (!event.start_iso) return false;
  const start = new Date(event.start_iso);
  if (Number.isNaN(start.getTime())) return false;
  return formatters.dateOnly.format(start) === todayKey;
});

const sortedForConflict = normalizedEvents
  .filter((event) => event.start_iso && event.end_iso)
  .map((event) => ({
    ...event,
    _start: new Date(event.start_iso).getTime(),
    _end: new Date(event.end_iso).getTime(),
  }))
  .filter((event) => Number.isFinite(event._start) && Number.isFinite(event._end))
  .sort((a, b) => a._start - b._start);

let hasConflict = false;
for (let i = 1; i < sortedForConflict.length; i += 1) {
  if (sortedForConflict[i]._start < sortedForConflict[i - 1]._end) {
    hasConflict = true;
    break;
  }
}

const nextEvent = normalizedEvents.find((event) => event.status === 'ongoing' || event.status === 'upcoming') || null;

return [{
  json: {
    user_id: $('Get Summary').first().json.body?.user_id || $('Get Summary').first().json.body?.userId || '',
    generated_at: new Date().toISOString(),
    calendar_summary: source.summary || '',
    next_event: nextEvent,
    events: normalizedEvents,
    source_metrics: {
      fetched_event_count: normalizedEvents.length,
      today_event_count: todayEvents.length,
      ongoing_event_count: normalizedEvents.filter((event) => event.status === 'ongoing').length,
      has_conflict: hasConflict,
      next_event_start: nextEvent?.start_iso || null,
    },
  },
}];

const raw = String($json.output || $json.text || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch {
    parsed = {};
  }
}

const fallbackMetrics = $('Prepare Calendar Summary Context').first().json.source_metrics || {};

return [{
  json: {
    success: true,
    user_id: $('Prepare Calendar Summary Context').first().json.user_id || '',
    generated_at: $('Prepare Calendar Summary Context').first().json.generated_at || new Date().toISOString(),
    summary: {
      domain: 'calendar',
      status: parsed.status || 'partial',
      priority: parsed.priority || 'medium',
      headline: parsed.headline || 'Ringkasan kalender belum tersedia',
      summary_points: Array.isArray(parsed.summary_points) ? parsed.summary_points.slice(0, 4) : [],
      recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations.slice(0, 3) : [],
      source_metrics: parsed.source_metrics || fallbackMetrics,
    },
  }
}];

return [{
  json: {
    success: true,
    user_id: $json.user_id || '',
    generated_at: $json.generated_at || new Date().toISOString(),
    summary: $json.summary || null,
  }
}];

const body = $json.body || {};
const jiraCredentials = body.jira_credentials || {};
const normalizeSubdomain = (value) => String(value || '')
  .trim()
  .replace(/^https?:\/\//i, '')
  .replace(/\/.*$/, '');

const jiraSubdomain = normalizeSubdomain(
  jiraCredentials.subdomain || body.jira_subdomain || body.jiraSubdomain || body.jira_base_url || body.jiraBaseUrl
);
const jiraEmail = String(jiraCredentials.email || body.jira_email || body.jiraEmail || '').trim();
const jiraApiToken = String(jiraCredentials.api_token || body.jira_api_token || body.jiraApiToken || '').trim();
const jiraAuthBase64 = String(
  body.jira_auth_base64 ||
  body.jiraAuthBase64 ||
  (jiraEmail && jiraApiToken ? Buffer.from(`${jiraEmail}:${jiraApiToken}`).toString('base64') : '')
).trim();
const userId = String(body.user_id || body.userId || '').trim();
const jql = String(body.jql || body.jira_jql || 'updated >= -30d ORDER BY updated DESC').trim();
const maxResults = Math.min(Math.max(Number(body.maxResults || body.jira_max_results || 25), 1), 50);

if (!jiraSubdomain) {
  throw new Error('jira_subdomain is required for jira summary');
}

if (!jiraAuthBase64) {
  throw new Error('jira_auth_base64 is required for jira summary');
}

return [{
  json: {
    user_id: userId,
    generated_at: new Date().toISOString(),
    jira_subdomain: jiraSubdomain,
    jira_auth_base64: jiraAuthBase64,
    jira_jql: jql,
    jira_max_results: maxResults
  }
}];

const source = $json || {};
const rawIssues = Array.isArray(source.issues)
  ? source.issues
  : Array.isArray(source.items)
    ? source.items
    : Array.isArray(source.data)
      ? source.data
      : [];

const getField = (issue, ...keys) => {
  for (const key of keys) {
    const value = key.split('.').reduce((acc, part) => acc?.[part], issue);
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return '';
};

const normalizeText = (value) => String(value || '').trim().toLowerCase();
const includesKeyword = (value, keywords) => {
  const normalized = normalizeText(value);
  return keywords.some((keyword) => normalized.includes(keyword));
};
const highPriorityKeywords = ['highest', 'high', 'critical', 'urgent'];
const blockedKeywords = ['blocked', 'blocker', 'waiting', 'stuck'];

const formatters = {
  dateOnly: new Intl.DateTimeFormat('id-ID', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  }),
  dateTime: new Intl.DateTimeFormat('id-ID', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  })
};

const formatDate = (value, mode = 'dateOnly') => {
  if (!value) return '-';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return formatters[mode].format(parsed);
};

const getStatusCategoryKey = (issue) => {
  const directKey = normalizeText(getField(issue, 'fields.status.statusCategory.key', 'status.statusCategory.key', 'statusCategory.key'));
  if (directKey) return directKey;
  const categoryName = normalizeText(getField(issue, 'fields.status.statusCategory.name', 'status.statusCategory.name', 'statusCategory.name'));
  if (categoryName.includes('progress')) return 'indeterminate';
  if (categoryName.includes('done')) return 'done';
  return 'new';
};

const isOverdueDate = (value) => {
  if (!value) return false;
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  parsed.setHours(0, 0, 0, 0);
  return parsed < today;
};

const isDateToday = (value) => {
  if (!value) return false;
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return false;
  return formatters.dateOnly.format(parsed) === formatters.dateOnly.format(new Date());
};

const normalizedIssues = rawIssues.map((issue, index) => {
  const issueKey = getField(issue, 'key', 'id', 'issueKey') || `ISSUE-${index + 1}`;
  const summary = getField(issue, 'fields.summary', 'summary', 'title') || 'Tanpa judul issue';
  const status = getField(issue, 'fields.status.name', 'status.name', 'status', 'state') || 'Unknown';
  const statusCategoryKey = getStatusCategoryKey(issue);
  const assignee = getField(issue, 'fields.assignee.displayName', 'assignee.displayName', 'assignee.name', 'assignee') || 'Belum ditugaskan';
  const priority = getField(issue, 'fields.priority.name', 'priority.name', 'priority') || 'Tanpa prioritas';
  const updatedAt = getField(issue, 'fields.updated', 'updated', 'updatedAt');
  const createdAt = getField(issue, 'fields.created', 'created', 'createdAt');
  const dueDate = getField(issue, 'fields.duedate', 'duedate', 'dueDate');
  const projectName = getField(issue, 'fields.project.name', 'project.name', 'project') || 'Project tidak diketahui';
  const issueType = getField(issue, 'fields.issuetype.name', 'issuetype.name', 'issueType') || 'Issue';
  const reporter = getField(issue, 'fields.reporter.displayName', 'reporter.displayName', 'reporter.name', 'reporter') || 'Tidak diketahui';
  const labels = Array.isArray(issue?.fields?.labels) ? issue.fields.labels : [];
  const isDone = statusCategoryKey === 'done';
  const isUnassigned = !getField(issue, 'fields.assignee.displayName', 'assignee.displayName', 'assignee.name', 'assignee');
  const isHighPriority = includesKeyword(priority, highPriorityKeywords);
  const isBlocked = includesKeyword(status, blockedKeywords) || labels.some((label) => includesKeyword(label, blockedKeywords));
  const isOverdue = !isDone && isOverdueDate(dueDate);
  const isUpdatedToday = isDateToday(updatedAt);
  const urgencyScore = (isOverdue ? 100 : 0) + (isBlocked ? 80 : 0) + (isHighPriority ? 50 : 0) + (statusCategoryKey === 'indeterminate' ? 25 : 0) + (isUnassigned ? 15 : 0);

  return {
    key: issueKey,
    summary,
    status,
    status_category_key: statusCategoryKey,
    assignee,
    priority,
    updated_at: updatedAt,
    updated_label: formatDate(updatedAt, 'dateTime'),
    created_at: createdAt,
    created_label: formatDate(createdAt, 'dateOnly'),
    due_date: dueDate,
    due_label: dueDate ? formatDate(dueDate, 'dateOnly') : null,
    project_name: projectName,
    issue_type: issueType,
    reporter,
    labels,
    is_done: isDone,
    is_unassigned: isUnassigned,
    is_high_priority: isHighPriority,
    is_blocked: isBlocked,
    is_overdue: isOverdue,
    is_updated_today: isUpdatedToday,
    urgency_score: urgencyScore
  };
});

const todoIssues = normalizedIssues.filter((issue) => issue.status_category_key === 'new');
const inProgressIssues = normalizedIssues.filter((issue) => issue.status_category_key === 'indeterminate');
const doneIssues = normalizedIssues.filter((issue) => issue.status_category_key === 'done');
const blockedIssues = normalizedIssues.filter((issue) => issue.is_blocked);
const highPriorityIssues = normalizedIssues.filter((issue) => issue.is_high_priority);
const unassignedIssues = normalizedIssues.filter((issue) => issue.is_unassigned);
const overdueIssues = normalizedIssues.filter((issue) => issue.is_overdue);
const updatedTodayIssues = normalizedIssues.filter((issue) => issue.is_updated_today);
const noDueDateInProgress = inProgressIssues.filter((issue) => !issue.due_date);

const assigneeCounts = normalizedIssues.reduce((acc, issue) => {
  if (issue.is_unassigned) return acc;
  acc[issue.assignee] = (acc[issue.assignee] || 0) + 1;
  return acc;
}, {});

const topAssignees = Object.entries(assigneeCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, issueCount]) => ({ name, issue_count: issueCount }));

const watchIssues = [...normalizedIssues]
  .sort((a, b) => {
    if (b.urgency_score !== a.urgency_score) return b.urgency_score - a.urgency_score;
    return new Date(b.updated_at || 0).getTime() - new Date(a.updated_at || 0).getTime();
  })
  .slice(0, 8)
  .map((issue) => ({
    key: issue.key,
    summary: issue.summary,
    status: issue.status,
    status_category_key: issue.status_category_key,
    assignee: issue.assignee,
    priority: issue.priority,
    updated_label: issue.updated_label,
    due_label: issue.due_label,
    project_name: issue.project_name,
    issue_type: issue.issue_type,
    flags: {
      is_overdue: issue.is_overdue,
      is_blocked: issue.is_blocked,
      is_high_priority: issue.is_high_priority,
      is_unassigned: issue.is_unassigned
    }
  }));

return [{
  json: {
    user_id: $('Prepare Jira Summary Request Data').first().json.user_id || '',
    generated_at: $('Prepare Jira Summary Request Data').first().json.generated_at || new Date().toISOString(),
    jira_scope: {
      jql: $('Prepare Jira Summary Request Data').first().json.jira_jql || '',
      max_results: $('Prepare Jira Summary Request Data').first().json.jira_max_results || normalizedIssues.length
    },
    watch_issues: watchIssues,
    source_metrics: {
      total_issues: normalizedIssues.length,
      todo_count: todoIssues.length,
      in_progress_count: inProgressIssues.length,
      done_count: doneIssues.length,
      blocked_count: blockedIssues.length,
      high_priority_count: highPriorityIssues.length,
      unassigned_count: unassignedIssues.length,
      overdue_count: overdueIssues.length,
      updated_today_count: updatedTodayIssues.length,
      no_due_date_in_progress_count: noDueDateInProgress.length,
      top_assignees: topAssignees
    }
  }
}];

const raw = String($json.output || $json.text || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
let parsed = {};

if (match) {
  try {
    parsed = JSON.parse(match[0]);
  } catch {
    parsed = {};
  }
}

const fallbackMetrics = $('Prepare Jira Summary Context').first().json.source_metrics || {};

return [{
  json: {
    success: true,
    user_id: $('Prepare Jira Summary Context').first().json.user_id || '',
    generated_at: $('Prepare Jira Summary Context').first().json.generated_at || new Date().toISOString(),
    summary: {
      domain: 'jira',
      status: parsed.status || 'partial',
      priority: parsed.priority || 'medium',
      headline: parsed.headline || 'Ringkasan Jira belum tersedia',
      summary_points: Array.isArray(parsed.summary_points) ? parsed.summary_points.slice(0, 4) : [],
      recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations.slice(0, 3) : [],
      source_metrics: parsed.source_metrics || fallbackMetrics
    }
  }
}];

return [{
  json: {
    success: true,
    user_id: $json.user_id || '',
    generated_at: $json.generated_at || new Date().toISOString(),
    summary: $json.summary || null
  }
}];
